def wrap(text, width):
    lines = []
    paragraphs = text.split('\n')

    for paragraph in paragraphs:
        # Split paragraph into words (maximal runs of non-space characters)
        words = paragraph.split()

        # Process each word - if longer than width, split it
        processed_words = []
        for word in words:
            while len(word) > width:
                processed_words.append(word[:width])
                word = word[width:]
            if word:
                processed_words.append(word)

        # Pack words greedily into lines
        if not processed_words:
            # Empty paragraph produces one empty line
            lines.append('')
        else:
            current_line = []
            current_length = 0

            for word in processed_words:
                word_len = len(word)
                # Check if word fits on current line
                if current_line:
                    # Need space before word
                    needed_length = current_length + 1 + word_len
                else:
                    # First word on line
                    needed_length = word_len

                if needed_length <= width:
                    current_line.append(word)
                    current_length = needed_length
                else:
                    # Word doesn't fit, start new line
                    if current_line:
                        lines.append(' '.join(current_line))
                    current_line = [word]
                    current_length = word_len

            # Add remaining line
            if current_line:
                lines.append(' '.join(current_line))

    return lines

